# Let me systematically find each rectangular frame
# A frame is a rectangle of one color with a different interior

def find_frames(grid, background=6):
    """Find all rectangular frames in the grid"""
    frames = []

    # Find all non-background colors
    colors_seen = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != background:
                colors_seen.add(grid[r][c])

    for color in colors_seen:
        # Find all cells with this color
        cells = [(r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] == color]

        if not cells:
            continue

        # Get bounding box
        rows = [r for r, c in cells]
        cols = [c for r, c in cells]
        rmin, rmax = min(rows), max(rows)
        cmin, cmax = min(cols), max(cols)

        # Verify it's a frame (border cells have color, interior may have other colors)
        is_frame = True
        interior_colors = set()

        for r in range(rmin, rmax + 1):
            for c in range(cmin, cmax + 1):
                if r == rmin or r == rmax or c == cmin or c == cmax:
                    # Border should be this color
                    if grid[r][c] != color:
                        is_frame = False
                else:
                    # Interior - collect colors
                    if grid[r][c] != background:
                        interior_colors.add(grid[r][c])

        if is_frame:
            frames.append({
                'color': color,
                'rmin': rmin, 'rmax': rmax,
                'cmin': cmin, 'cmax': cmax,
                'h': rmax - rmin + 1,
                'w': cmax - cmin + 1,
                'interior_colors': interior_colors
            })

    return frames

frames = find_frames(grid)
for i, frame in enumerate(frames):
    print(f"Frame {i}: color={frame['color']} ({frame['h']}x{frame['w']}), r:{frame['rmin']}-{frame['rmax']}, c:{frame['cmin']}-{frame['cmax']}, interior={frame['interior_colors']}")

